//! Diagnostics commands (GUI_UX_SPEC §19, UI-060 / #403): the cache/log
//! paths the 診断情報 sheet displays and the ログフォルダを開く action.
//! engine.rs tees worker stderr into logs/engine-<unix>.log per spawn
//! so the folder this reveals actually contains engine diagnostics.

use serde::Serialize;
use std::path::{Path, PathBuf};

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DiagnosticsPaths {
    cache: String,
    logs: String,
}

fn app_dir(app: &tauri::AppHandle, name: &str) -> Result<PathBuf, String> {
    use tauri::Manager;
    let dir = app
        .path()
        .app_data_dir()
        .map_err(|e| format!("app_data_dir: {e}"))?
        .join(name);
    std::fs::create_dir_all(&dir).map_err(|e| format!("create {}: {e}", dir.display()))?;
    Ok(dir)
}

/// <app_data>/logs — created on demand so reveal_log_folder always
/// has a real directory to open. Shared with engine.rs's stderr tee.
pub(crate) fn log_dir(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    app_dir(app, "logs")
}

/// <app_data>/cache — transcription artifacts live here. Created so
/// the reported path is real, mirroring log_dir.
fn cache_dir(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    app_dir(app, "cache")
}

/// diagnostics_paths: the §19 cache/log locations. Both directories are
/// created so the sheet never reports a path that does not exist yet.
#[tauri::command]
pub fn diagnostics_paths(app: tauri::AppHandle) -> Result<DiagnosticsPaths, String> {
    Ok(DiagnosticsPaths {
        cache: cache_dir(&app)?.to_string_lossy().into_owned(),
        logs: log_dir(&app)?.to_string_lossy().into_owned(),
    })
}

/// reveal_log_folder: ログフォルダを開く — reuses the export module's
/// explorer reveal, which requires an existing directory (log_dir just
/// created it).
#[tauri::command]
pub fn reveal_log_folder(app: tauri::AppHandle) -> Result<(), String> {
    let dir = log_dir(&app)?;
    crate::export::reveal_in_explorer(dir.to_string_lossy().into_owned())
}

/// Per-spawn engine stderr log (engine-<unix>.log), retention-pruned.
/// Returns a buffered writer or None when the log dir is unavailable —
/// logging must never block the engine spawn itself.
pub(crate) fn engine_log_file(
    app: &tauri::AppHandle,
) -> Option<std::io::BufWriter<std::fs::File>> {
    let dir = log_dir(app).ok()?;
    prune_engine_logs(&dir);
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    std::fs::File::create(dir.join(format!("engine-{secs}.log")))
        .ok()
        .map(std::io::BufWriter::new)
}

/// Retention: keep the newest engine-*.log files so a crash-looping
/// engine cannot fill the disk. Lexicographic oldest-first order works
/// because the unix-second stem stays fixed-width this century.
fn prune_engine_logs(dir: &Path) {
    const MAX_ENGINE_LOGS: usize = 10;
    let mut logs: Vec<PathBuf> = match std::fs::read_dir(dir) {
        Ok(rd) => rd
            .flatten()
            .map(|e| e.path())
            .filter(|p| {
                p.is_file()
                    && p
                        .file_name()
                        .and_then(|n| n.to_str())
                        .map(|n| n.starts_with("engine-") && n.ends_with(".log"))
                        .unwrap_or(false)
            })
            .collect(),
        Err(_) => return,
    };
    // The caller is about to add one more file.
    if logs.len() < MAX_ENGINE_LOGS {
        return;
    }
    let excess = logs.len() + 1 - MAX_ENGINE_LOGS;
    logs.sort();
    for p in logs.into_iter().take(excess) {
        let _ = std::fs::remove_file(p);
    }
}

//! ENG-002: spawn the Python engine sidecar (`python -m hornscribe.worker`)
//! and relay its NDJSON protocol to the frontend over a Tauri channel.
//!
//! Security model (same pattern as lib.rs's self-limiting commands): the
//! spawned process is always the fixed `hornscribe.worker` protocol —
//! the frontend cannot choose the program, the arguments, or the cwd.
//! The engine resolves in this order (#83):
//!
//! 1. `HORNSCRIBE_ENGINE` — path to a frozen engine binary
//!    (explicit operator override, speaks NDJSON directly);
//! 2. `HORNSCRIBE_PYTHON` — interpreter override (dev/debug);
//! 3. a bundled `engine/hornscribe-engine[.exe]` next to the app
//!    resources or the executable (packaged builds);
//! 4. repo-local virtualenvs found by walking ancestors of
//!    `CARGO_MANIFEST_DIR` for `.venv-*/Scripts/python.exe` /
//!    `.venv/Scripts/python.exe` (dev checkouts);
//! 5. `python`/`py -3` on PATH (system installs).
//!
//! `HORNSCRIBE_PYTHONPATH` overrides the module search path; otherwise the
//! repo's `python/` directory (the `hornscribe` package root) is injected
//! when it exists. Frozen binaries ignore PYTHONPATH entirely.
//!
//! Channel protocol (one JSON object per send):
//!   `{kind:"line",   line}`   — one stdout NDJSON frame
//!   `{kind:"stderr", line}`   — one stderr line (diagnostics only)
//!   `{kind:"exit",   code}`   — process exited; `code` may be null

use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdin, Command, Stdio};
use std::sync::Mutex;

use serde_json::json;
use tauri::{ipc::Channel, Manager};

/// The single in-flight engine process. One sidecar per app — the worker
/// itself enforces one job at a time (PROTOCOL.md).
struct EngineState {
    child: Child,
    /// `Option` so `engine_close_stdin` can take()+drop it — dropping the
    /// pipe is the EOF the worker treats as a graceful shutdown.
    stdin: Option<ChildStdin>,
}

static ENGINE: Mutex<Option<EngineState>> = Mutex::new(None);

/// How the engine process is launched (#83). A frozen binary speaks the
/// worker NDJSON protocol directly; a Python interpreter is invoked as
/// `python -m hornscribe.worker` with an optional PYTHONPATH.
enum SpawnTarget {
    Binary(PathBuf),
    Python { exe: PathBuf, pythonpath: Option<PathBuf> },
}

/// `engine_spawn`: start the sidecar; stream frames over `channel`.
/// Fails with a human-readable string when no usable Python is found.
#[tauri::command]
pub fn engine_spawn(
    channel: Channel<serde_json::Value>,
    app: tauri::AppHandle,
) -> Result<(), String> {
    let mut guard = ENGINE.lock().map_err(|_| "engine lock")?;
    if guard.is_some() {
        return Err("ENGINE_ALREADY_RUNNING".to_string());
    }
    let target = resolve_engine(&app)?;

    let mut cmd = match &target {
        SpawnTarget::Binary(exe) => Command::new(exe),
        SpawnTarget::Python { exe, pythonpath } => {
            let mut c = Command::new(exe);
            c.args(["-m", "hornscribe.worker"]);
            if let Some(pp) = pythonpath {
                c.env("PYTHONPATH", pp);
            }
            c
        }
    };
    cmd
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        // The worker pins its own UTF-8/\n streams; unbuffered keeps
        // progress frames flowing without relying on flush timing.
        .env("PYTHONUNBUFFERED", "1")
        .env("PYTHONUTF8", "1");
    // No console window flash on Windows for the spawned interpreter.
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        const CREATE_NO_WINDOW: u32 = 0x0800_0000;
        cmd.creation_flags(CREATE_NO_WINDOW);
    }

    let mut child = cmd
        .spawn()
        .map_err(|e| {
            let exe = match &target {
                SpawnTarget::Binary(p) | SpawnTarget::Python { exe: p, .. } => p.clone(),
            };
            format!("spawn {}: {e}", exe.display())
        })?;
    let stdin = child
        .stdin
        .take()
        .ok_or("child stdin was not piped")?;
    let stdout = child
        .stdout
        .take()
        .ok_or("child stdout was not piped")?;
    let stderr = child
        .stderr
        .take()
        .ok_or("child stderr was not piped")?;

    // stdout -> protocol lines.
    let line_chan = channel.clone();
    std::thread::Builder::new()
        .name("hornscribe-engine-stdout".into())
        .spawn(move || {
            let reader = BufReader::new(stdout);
            for line in reader.lines() {
                match line {
                    Ok(l) if !l.is_empty() => {
                        let _ = line_chan.send(json!({"kind":"line","line":l}));
                    }
                    Ok(_) => {}
                    Err(_) => break,
                }
            }
        })
        .map_err(|e| format!("spawn stdout reader: {e}"))?;

    // stderr -> diagnostics lines + a persistent per-spawn log file
    // (#403: 診断情報 の ログフォルダを開く needs a real file to show).
    let err_chan = channel.clone();
    let mut log_file = crate::diagnostics::engine_log_file(&app);
    std::thread::Builder::new()
        .name("hornscribe-engine-stderr".into())
        .spawn(move || {
            let reader = BufReader::new(stderr);
            for line in reader.lines() {
                match line {
                    Ok(l) if !l.is_empty() => {
                        if let Some(f) = log_file.as_mut() {
                            let _ = writeln!(f, "{l}");
                        }
                        let _ = err_chan.send(json!({"kind":"stderr","line":l}));
                    }
                    Ok(_) => {}
                    Err(_) => break,
                }
            }
        })
        .map_err(|e| format!("spawn stderr reader: {e}"))?;

    *guard = Some(EngineState {
        child,
        stdin: Some(stdin),
    });
    drop(guard);

    // Exit monitor: try_wait on a short poll so engine_kill stays
    // responsive (a blocking wait() would hold the child forever).
    std::thread::Builder::new()
        .name("hornscribe-engine-exit".into())
        .spawn(move || loop {
            let exited = {
                let mut guard = ENGINE.lock().unwrap_or_else(|e| e.into_inner());
                match guard.as_mut() {
                    Some(state) => match state.child.try_wait() {
                        Ok(Some(status)) => {
                            *guard = None;
                            Some(status.code())
                        }
                        Ok(None) => None,
                        Err(_) => {
                            *guard = None;
                            Some(None)
                        }
                    },
                    // Engine was killed/closed from the frontend.
                    None => return,
                }
            };
            match exited {
                Some(code) => {
                    let _ = channel.send(json!({"kind":"exit","code":code}));
                    return;
                }
                None => std::thread::sleep(std::time::Duration::from_millis(40)),
            }
        })
        .map_err(|e| format!("spawn exit monitor: {e}"))?;

    Ok(())
}

/// `engine_write`: one NDJSON request line to the worker's stdin.
#[tauri::command]
pub fn engine_write(line: String) -> Result<(), String> {
    let mut guard = ENGINE.lock().map_err(|_| "engine lock")?;
    let state = guard.as_mut().ok_or("ENGINE_NOT_RUNNING")?;
    let stdin = state.stdin.as_mut().ok_or("engine stdin is closed")?;
    stdin
        .write_all(line.as_bytes())
        .and_then(|()| stdin.write_all(b"\n"))
        .and_then(|()| stdin.flush())
        .map_err(|e| format!("engine stdin: {e}"))
}

/// `engine_close_stdin`: drop stdin so the worker sees EOF and performs
/// its graceful shutdown (worker.py contract).
#[tauri::command]
pub fn engine_close_stdin() -> Result<(), String> {
    let mut guard = ENGINE.lock().map_err(|_| "engine lock")?;
    if let Some(state) = guard.as_mut() {
        drop(state.stdin.take());
    }
    Ok(())
}

/// `engine_kill`: terminate the sidecar immediately (the documented
/// terminate/restart fallback for non-interruptible jobs).
#[tauri::command]
pub fn engine_kill() -> Result<(), String> {
    let mut guard = ENGINE.lock().map_err(|_| "engine lock")?;
    if let Some(mut state) = guard.take() {
        let _ = state.child.kill();
        let _ = state.child.wait();
    }
    Ok(())
}

/// App-exit cleanup: never leak the sidecar past the shell process.
pub fn kill_engine_on_exit() {
    if let Ok(mut guard) = ENGINE.lock() {
        if let Some(mut state) = guard.take() {
            let _ = state.child.kill();
            let _ = state.child.wait();
        }
    }
}

/// Resolve how to launch the engine (#83). Returns either a frozen
/// binary or a Python interpreter + module path. The `pythonpath` is
/// `None` when the interpreter already has `hornscribe` importable
/// (venv installs) — frozen binaries never see it.
fn resolve_engine(app: &tauri::AppHandle) -> Result<SpawnTarget, String> {
    let repo_python_dir = find_repo_python_dir();

    // #83: explicit frozen-engine override wins — a packaged layout can
    // also point at a portable binary via env without rebuilding.
    if let Ok(explicit) = std::env::var("HORNSCRIBE_ENGINE") {
        let p = PathBuf::from(explicit);
        if p.is_file() {
            return Ok(SpawnTarget::Binary(p));
        }
        return Err(format!("HORNSCRIBE_ENGINE is not a file: {}", p.display()));
    }

    if let Ok(explicit) = std::env::var("HORNSCRIBE_PYTHON") {
        let p = PathBuf::from(explicit);
        if p.is_file() {
            return Ok(SpawnTarget::Python {
                exe: p,
                pythonpath: repo_python_dir,
            });
        }
        return Err(format!("HORNSCRIBE_PYTHON is not a file: {}", p.display()));
    }

    // #83: bundled frozen engine (packaged builds). Checked before the
    // dev venvs so an installed app never reaches into a source checkout.
    for candidate in bundled_engine_paths(app) {
        if candidate.is_file() {
            return Ok(SpawnTarget::Binary(candidate));
        }
    }

    // Repo-local venvs (dev checkouts and the bundled `engine/` layout).
    for candidate in local_venv_pythons() {
        if candidate.is_file() {
            return Ok(SpawnTarget::Python {
                exe: candidate,
                pythonpath: repo_python_dir.clone(),
            });
        }
    }

    // PATH fallbacks: `python` then the `py` launcher.
    for exe in ["python", "py"] {
        if which_exists(exe) {
            return Ok(SpawnTarget::Python {
                exe: PathBuf::from(exe),
                pythonpath: repo_python_dir,
            });
        }
    }
    Err(
        "no engine runtime found (bundle engine/hornscribe-engine, set \
         HORNSCRIBE_ENGINE/HORNSCRIBE_PYTHON, or install the engine environment)"
            .to_string(),
    )
}

/// Candidate locations for the frozen engine binary (#83).
///
/// Packaged builds ship `engine/hornscribe-engine[.exe]` as a Tauri
/// resource (see scripts/build_engine.py + tauri.conf.json). The exact
/// resource_dir layout varies by installer, so we probe the resource
/// dir, its `resources/` child, and the executable's own directory —
/// the last also covers portable-zip layouts without an installer.
fn bundled_engine_paths(app: &tauri::AppHandle) -> Vec<PathBuf> {
    const EXE: &str = if cfg!(windows) {
        "hornscribe-engine.exe"
    } else {
        "hornscribe-engine"
    };
    let mut roots: Vec<PathBuf> = Vec::new();
    if let Ok(dir) = app.path().resource_dir() {
        roots.push(dir.clone());
        roots.push(dir.join("resources"));
    }
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            roots.push(dir.to_path_buf());
        }
    }
    roots
        .into_iter()
        .map(|root| root.join("engine").join(EXE))
        .collect()
}

/// `<repo>/python` — the hornscribe package root — found by walking up
/// from the crate manifest. `HORNSCRIBE_PYTHONPATH` wins when set.
fn find_repo_python_dir() -> Option<PathBuf> {
    if let Ok(explicit) = std::env::var("HORNSCRIBE_PYTHONPATH") {
        let p = PathBuf::from(explicit);
        if p.is_dir() {
            return Some(p);
        }
    }
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR"));
    for dir in manifest.ancestors() {
        let candidate = dir.join("python").join("hornscribe");
        if candidate.is_dir() {
            return Some(dir.join("python"));
        }
    }
    None
}

/// Repo-local virtualenv interpreters, best-first. The worker
/// hard-requires music21 and benefits from basic_pitch, so envs are
/// scored by what they can actually run: a stale basic-pitch-only env
/// (no music21) would crash the worker on import and must rank below a
/// plain `.venv` that can at least serve the engine honestly.
fn local_venv_pythons() -> Vec<PathBuf> {
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut roots: Vec<PathBuf> = Vec::new();
    for dir in manifest.ancestors() {
        if let Ok(entries) = std::fs::read_dir(dir) {
            for entry in entries.flatten() {
                let name = entry.file_name();
                let name = name.to_string_lossy();
                if name.starts_with(".venv") && entry.path().is_dir() {
                    roots.push(entry.path());
                }
            }
        }
    }
    // Score by installed packages: music21 is a hard import, basic_pitch
    // unlocks the real model. Best score first; name tiebreak keeps
    // dev runs deterministic.
    let site_has = |v: &Path, pkg: &str| {
        v.join("Lib").join("site-packages").join(pkg).is_dir()
    };
    let score = |v: &Path| {
        (!site_has(v, "music21") as u8) * 2 + (!site_has(v, "basic_pitch") as u8)
    };
    roots.sort_by(|a, b| {
        score(a).cmp(&score(b)).then_with(|| {
            a.file_name()
                .unwrap_or_default()
                .cmp(b.file_name().unwrap_or_default())
        })
    });
    roots
        .into_iter()
        .map(|v| v.join("Scripts").join("python.exe"))
        .collect()
}

fn which_exists(exe: &str) -> bool {
    // Cheap PATH probe: `where.exe` is present on every supported Windows.
    Command::new("where")
        .arg(exe)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

//! HornScribe desktop shell — UI-001 spike + UI-020 import plumbing.
//!
//! Security model: no fs/asset-protocol/shell/http grants. The only plugin
//! is `tauri-plugin-dialog`, capability-scoped to `dialog:allow-open` so the
//! frontend can show the native picker (no save/message variants granted).
//!
//! Because the ACL does not govern app-defined commands, the file-reading
//! commands below self-limit instead of relying on a permission grant:
//! `read_audio_bytes` serves only the advertised audio extensions with a
//! hard size cap, and `read_project_file` serves only `*.hornscribe.json`
//! project documents. Both are read-only — the source file is never
//! modified (GUI_UX_SPEC §3 / FND-001 SourceAudioRef).

use serde::Serialize;

mod audio;
mod capture;
mod diagnostics;
mod engine;
mod export;

/// Audio containers the import UX advertises (GUI_UX_SPEC §3 formats line).
/// The frontend rejects other extensions before reaching this command; the
/// allowlist here is the Rust-side backstop so the command cannot be turned
/// into a general file reader.
const AUDIO_EXTENSIONS: [&str; 5] = ["wav", "mp3", "flac", "m4a", "ogg"];

/// HornScribe project document suffix (python/hornscribe/project/model.py).
// #389: shared with export.rs's project_write (the shell-side save).
pub(crate) const PROJECT_FILE_SUFFIX: &str = ".hornscribe.json";

/// 512 MiB — far above any realistic horn recording (~90 MB for 10 min of
/// PCM16 stereo 44.1 kHz); guards against unbounded reads.
const MAX_AUDIO_BYTES: u64 = 512 * 1024 * 1024;
/// Project JSON embeds the canonical score + both MusicXML bodies
/// (#218), so long pieces legitimately exceed the old 16 MiB cap —
/// the save side has no limit and the open side must not reject
/// projects it wrote (#262). 128 MiB is far above any realistic
/// score while still guarding against unbounded reads.
const MAX_PROJECT_BYTES: u64 = 128 * 1024 * 1024;

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct ShellInfo {
    app_name: String,
    version: String,
    rust_target_env: String,
}

#[tauri::command]
fn shell_info(app: tauri::AppHandle) -> ShellInfo {
    let pkg = app.package_info();
    ShellInfo {
        app_name: pkg.name.clone(),
        version: pkg.version.to_string(),
        rust_target_env: (if cfg!(target_env = "msvc") {
            "msvc"
        } else if cfg!(target_env = "gnu") {
            "gnu"
        } else {
            "other"
        })
        .to_string(),
    }
}

/// Read a user-selected audio file and return its bytes over raw IPC so the
/// webview can decode it (WebAudio `decodeAudioData`) and hash it
/// (WebCrypto SHA-256, mirroring `hash_file_sha256` in the project schema).
/// Read-only, extension-allowlisted, size-capped.
#[tauri::command]
fn read_audio_bytes(path: String) -> Result<tauri::ipc::Response, String> {
    let ext = std::path::Path::new(&path)
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    if !AUDIO_EXTENSIONS.contains(&ext.as_str()) {
        return Err(format!("unsupported audio extension: {ext}"));
    }
    let meta = std::fs::metadata(&path).map_err(|e| format!("{path}: {e}"))?;
    if !meta.is_file() {
        return Err(format!("not a file: {path}"));
    }
    if meta.len() > MAX_AUDIO_BYTES {
        return Err(format!("audio file too large: {} bytes", meta.len()));
    }
    let bytes = std::fs::read(&path).map_err(|e| format!("{path}: {e}"))?;
    Ok(tauri::ipc::Response::new(bytes))
}

/// Read a `*.hornscribe.json` project document (schema v1, FND-001) so the
/// import flow can recover sourceAudio.originalPath/contentHash for the
/// relink UX. Read-only, suffix-restricted, size-capped.
#[tauri::command]
fn read_project_file(path: String) -> Result<tauri::ipc::Response, String> {
    if !path.to_ascii_lowercase().ends_with(PROJECT_FILE_SUFFIX) {
        return Err(format!("not a HornScribe project file: {path}"));
    }
    let meta = std::fs::metadata(&path).map_err(|e| format!("{path}: {e}"))?;
    if !meta.is_file() {
        return Err(format!("not a file: {path}"));
    }
    if meta.len() > MAX_PROJECT_BYTES {
        return Err(format!("project file too large: {} bytes", meta.len()));
    }
    let bytes = std::fs::read(&path).map_err(|e| format!("{path}: {e}"))?;
    Ok(tauri::ipc::Response::new(bytes))
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_dialog::init())
        // #230: media custom scheme — token-scoped audio streaming for
        // <audio> playback (Range-capable; only paths registered by
        // audio_probe resolve).
        .register_asynchronous_uri_scheme_protocol(
            "media",
            audio::media_scheme_handler,
        )
        .invoke_handler(tauri::generate_handler![
            shell_info,
            read_audio_bytes,
            read_project_file,
            audio::audio_probe,
            capture::capture_start,
            capture::capture_stop,
            capture::capture_cancel,
            capture::capture_status,
            capture::capture_devices,
            capture::capture_pause,
            capture::capture_resume,
            capture::recordings_info,
            capture::open_recordings_dir,
            capture::clear_recordings,
            capture::recordings_list,
            capture::delete_recording,
            capture::copy_recording_to_managed,
            capture::sources_info,
            capture::sources_list,
            capture::open_sources_dir,
            capture::delete_source,
            capture::source_refs_update,
            capture::source_refs_index,
            engine::engine_spawn,
            engine::engine_write,
            engine::engine_close_stdin,
            engine::engine_kill,
            diagnostics::diagnostics_paths,
            diagnostics::reveal_log_folder,
            export::export_pick_dir,
            export::export_default_dir,
            export::export_check_existing,
            export::export_run,
            export::export_cancel,
            export::detect_tools,
            export::probe_tool_path,
            export::reveal_in_explorer,
            export::project_save_path,
            export::project_write,
            export::project_autosave_write,
            export::project_autosave_status,
            export::project_autosave_clear,
            export::open_in_musescore,
        ])
        .build(tauri::generate_context!())
        .expect("error while building HornScribe shell")
        .run(|_app, event| {
            if let tauri::RunEvent::Exit = event {
                engine::kill_engine_on_exit();
            }
        });
}

