/**
 * DiagnosticsPort — data seam for the 診断情報 surface (UI-060;
 * GUI_UX_SPEC §19: versions / tool status / cache+log paths / actions).
 *
 * Same gate pattern as `src/sidecar/port.ts` (UI-040) and
 * `src/export/port.ts`: the shell renders whatever the port can honestly
 * report — `collect()` resolves with per-field `null`/`unknown` instead of
 * rejecting, so diagnostics stays usable even with no engine.
 *
 * Gate:
 * - plain browser → {@link MockDiagnosticsPort}: an in-process fake that
 *   populates every field so the full surface is reviewable in `vite dev`;
 * - Tauri webview → {@link ShellDiagnosticsPort}: reports shell-side truth
 *   (app version via `shell_info`, no engine/tool probe — there is no
 *   spawn/fs bridge yet), and the actions report honest failure rather
 *   than pretending.
 */

import { invoke } from "@tauri-apps/api/core";
import pkg from "../../package.json";
import { getShellInfo, isTauriRuntime } from "../tauri/bridge";
import { MockDiagnosticsPort } from "./mockPort";
import { detectTools, resolveToolWithOverride } from "./toolProbe";
import type {
  DiagnosticsInfo,
  EngineInfo,
  ToolPathOverrides,
  WorkerStatus,
} from "./types";

export interface DiagnosticsPort {
  /**
   * Gather the §19 surface. `overrides` carries the user-specified tool
   * paths from 設定 → ツール; non-empty paths override probing.
   * Never rejects: unavailable data is null/"unknown", so the sheet can
   * always render an honest picture.
   */
  collect(overrides?: ToolPathOverrides): Promise<DiagnosticsInfo>;
  /**
   * Copy already-formatted diagnostics text to the OS clipboard.
   * Resolves false when no clipboard path exists — the caller announces
   * the failure (clipboard may be absent/denied in some webviews).
   */
  copyText(text: string): Promise<boolean>;
  /** ログフォルダを開く — false when the bridge cannot reveal folders. */
  openLogFolder(): Promise<boolean>;
  /** エンジンを再起動 — false while no supervisor exists to restart. */
  restartEngine(): Promise<boolean>;
}

/**
 * Session-side view the shell port reports live (#403). The app wires
 * `sessionSnapshot` to `TranscriptionSession.getSnapshot()`; without it
 * the worker fields stay honest (unavailable) instead of inventing state.
 */
export interface DiagnosticsSessionView {
  readonly engine: string;
  /** Wire-shape engine identity (all fields optional on the protocol —
   *  the port fills display fallbacks when rendering). */
  readonly engineInfo: {
    readonly name?: string;
    readonly version?: string;
    readonly python?: string;
    readonly platform?: string;
    readonly pid?: number;
  } | null;
  readonly protocolVersion: number | null;
  /** Last completed job's result meta backend id; null before the first
   *  transcription. */
  readonly backend: string | null;
}

export interface ShellDiagnosticsDeps {
  /** Live view of the sidecar session (worker liveness, engine identity,
   *  negotiated protocol version, last backend). */
  sessionSnapshot?: () => DiagnosticsSessionView | null;
  /** エンジンを再起動 — TranscriptionSession.restartEngine in the shell. */
  restartEngine?: () => Promise<unknown>;
}

interface DiagnosticsPathsWire {
  cache: string;
  logs: string;
}

async function diagnosticsPaths(): Promise<DiagnosticsPathsWire | null> {
  try {
    return await invoke<DiagnosticsPathsWire>("diagnostics_paths");
  } catch {
    return null;
  }
}

/** ADR-0002 worker vocabulary: supervised-but-idle (offline, never
 *  started) maps to stopped; unavailable is reserved for "the port has
 *  no session to ask". */
function toWorkerStatus(engine: string): WorkerStatus {
  switch (engine) {
    case "ready":
    case "starting":
      return "running";
    case "offline":
    case "crashed":
    case "unresponsive":
    case "closed":
      return "stopped";
    default:
      return "unavailable";
  }
}

/** Wire → §19 row: the sheet renders name/version unconditionally, so
 *  missing fields get honest placeholders rather than "undefined". */
function toEngineInfo(
  info: DiagnosticsSessionView["engineInfo"],
): EngineInfo | null {
  if (!info) return null;
  return {
    name: info.name ?? "hornscribe-engine",
    version: info.version ?? "?",
    ...(info.python !== undefined ? { python: info.python } : {}),
    ...(info.platform !== undefined ? { platform: info.platform } : {}),
    ...(info.pid !== undefined ? { pid: info.pid } : {}),
  };
}

// verovio is a bundled, actively-used dependency (src/score/verovio.ts) —
// the declared version in package.json is the shipped one, so the row
// can report found instead of unknown (#403).
const VEROVIO_VERSION = pkg.dependencies.verovio;

/**
 * Shell port: app-shell truth (version, tool probes, cache/log paths)
 * plus whatever the wired session honestly reports. Every bridge call
 * degrades per-field to null/"unknown" rather than rejecting.
 */
export class ShellDiagnosticsPort implements DiagnosticsPort {
  constructor(private readonly deps: ShellDiagnosticsDeps = {}) {}

  async collect(overrides?: ToolPathOverrides): Promise<DiagnosticsInfo> {
    const shell = await getShellInfo();
    // Real detection exists (export.detect_tools) — report it instead
    // of the old blanket "unknown"; overrides verified via #363 probe.
    const tools = await detectTools();
    const view = this.deps.sessionSnapshot?.() ?? null;
    const [museScore, ffmpeg, paths] = await Promise.all([
      resolveToolWithOverride(
        tools?.museScore ?? { status: "unknown" },
        overrides?.museScorePath,
      ),
      resolveToolWithOverride(
        tools?.ffmpeg ?? { status: "unknown" },
        overrides?.ffmpegPath,
      ),
      diagnosticsPaths(),
    ]);
    return {
      appVersion: shell?.version ?? null,
      engine: toEngineInfo(view?.engineInfo ?? null),
      protocolVersion: view?.protocolVersion ?? null,
      backend: view?.backend ?? null,
      tools: {
        ffmpeg,
        museScore,
        verovio: { status: "found", version: VEROVIO_VERSION },
        // The waveform is a custom SVG renderer — no wavesurfer dep to
        // report, so unknown stays the honest answer.
        wavesurfer: { status: "unknown" },
      },
      paths: paths ?? { cache: null, logs: null },
      workerStatus: view ? toWorkerStatus(view.engine) : "unavailable",
    };
  }
  async copyText(text: string): Promise<boolean> {
    return clipboardWrite(text);
  }
  async openLogFolder(): Promise<boolean> {
    try {
      await invoke("reveal_log_folder");
      return true;
    } catch {
      return false;
    }
  }
  async restartEngine(): Promise<boolean> {
    if (!this.deps.restartEngine) return false;
    try {
      await this.deps.restartEngine();
      return true;
    } catch {
      return false;
    }
  }
}

/** Clipboard write shared by both ports (browser + webview). */
export async function clipboardWrite(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    return false;
  }
}

export function createDefaultDiagnosticsPort(
  deps?: ShellDiagnosticsDeps,
): DiagnosticsPort {
  if (isTauriRuntime()) return new ShellDiagnosticsPort(deps);
  return MockDiagnosticsPort.withDevOverrides();
}

/**
 * TranscriptionSession + jobView tracker tests (UI-040).
 *
 * Covers the app-facing state machine: start → stage/progress tracking →
 * terminal transitions, cooperative cancel with the honest `cancelling`
 * state, job failure → 再試行 surface, worker crash/unresponsive →
 * エンジンを再起動 recovery, review-issue count extraction, and the
 * stage-honesty rules (no `stage` field → no claimed position).
 */

import { describe, expect, it } from "vitest";
import { MockSidecarPort } from "./mockPort";
import {
  TranscriptionSession,
  type SessionSnapshot,
} from "./session";
import {
  createJobView,
  initialStages,
  markCancelling,
  markJobDead,
  reduceJobEvent,
  TRANSCRIPTION_STAGE_IDS,
} from "./jobView";
import {
  extractReviewIssueCount,
  reviewReasonCopyKey,
} from "./review";
import { ERR, type JobEventPayload } from "./protocol";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function until(cond: () => boolean, ms = 1500): Promise<void> {
  const deadline = Date.now() + ms;
  while (!cond()) {
    if (Date.now() > deadline) throw new Error("timed out waiting for condition");
    await sleep(2);
  }
}

function makeSession(port = new MockSidecarPort()) {
  const session = new TranscriptionSession({
    portFactory: () => port,
    clientOptions: {
      requestTimeoutMs: 250,
      handshakeTimeoutMs: 500,
      watchdogMs: 40,
      pingTimeoutMs: 30,
    },
  });
  const snaps: SessionSnapshot[] = [];
  session.subscribe((s) => snaps.push(s));
  return { session, port, snaps };
}

const FAST = { steps: 7, stepDurationMs: 2 };

describe("jobView tracker (pure)", () => {
  const ev = (over: Partial<JobEventPayload>): JobEventPayload => ({
    jobId: "job-1",
    phase: "progress",
    ...over,
  });

  it("stages advance only on reported stage fields, in order", () => {
    let v = createJobView("job-1", "transcription", 0);
    expect(v.stages.every((s) => s.status === "pending")).toBe(true);
    v = reduceJobEvent(v, ev({ stage: "preparing_audio" }));
    expect(v.stages[0].status).toBe("active");
    v = reduceJobEvent(v, ev({ stage: "quantizing", progress: 0.6 }));
    expect(v.stages[0].status).toBe("done");
    expect(v.stages[4].status).toBe("active");
    expect(v.activeStageIndex).toBe(4);
    expect(v.progress).toBeCloseTo(0.6);
  });

  it("ignores unknown stage ids and out-of-order noise safely", () => {
    let v = createJobView("job-1", "transcription", 0);
    v = reduceJobEvent(v, ev({ stage: "not_a_stage" }));
    expect(v.stages.every((s) => s.status === "pending")).toBe(true);
    expect(v.hasStageInfo).toBe(false);
    // A stage going "backwards" is ignored (monotonic honesty).
    v = reduceJobEvent(v, ev({ stage: "building_score" }));
    v = reduceJobEvent(v, ev({ stage: "preparing_audio" }));
    expect(v.activeStageIndex).toBe(5);
  });

  it("#385: step counts track the active stage and reset on advance", () => {
    let v = createJobView("job-1", "transcription", 0);
    expect(v.stepCount).toBeNull();
    v = reduceJobEvent(v, ev({ stage: "preparing_audio" }));
    expect(v.stepCount).toBeNull(); // boundary alone: indeterminate
    v = reduceJobEvent(
      v,
      ev({ stage: "preparing_audio", step: 1, totalSteps: 2 }),
    );
    expect(v.stepCount).toEqual({ step: 1, total: 2 });
    // Same-stage events keep the last count; a new stage clears it.
    v = reduceJobEvent(
      v,
      ev({ stage: "preparing_audio", step: 2, totalSteps: 2 }),
    );
    v = reduceJobEvent(v, ev({ stage: "transcribing" }));
    expect(v.stepCount).toBeNull();
    // Step counts never masquerade as a job fraction.
    expect(v.progress).toBeNull();
  });

  it("a job without stage info stays honest (all pending, real progress)", () => {
    let v = createJobView("job-1", "demoLongTask", 0);
    v = reduceJobEvent(v, ev({ progress: 0.4 }));
    v = reduceJobEvent(v, ev({ progress: 0.7 }));
    expect(v.hasStageInfo).toBe(false);
    expect(v.stages.every((s) => s.status === "pending")).toBe(true);
    expect(v.progress).toBeCloseTo(0.7);
  });

  it("terminal completed marks every stage done; later events are ignored", () => {
    let v = createJobView("job-1", "transcription", 0);
    v = reduceJobEvent(v, ev({ stage: "transcribing" }));
    v = reduceJobEvent(v, ev({ phase: "completed", result: { ok: true } }));
    expect(v.phase).toBe("completed");
    expect(v.stages.every((s) => s.status === "done")).toBe(true);
    const after = reduceJobEvent(v, ev({ stage: "preparing_audio" }));
    expect(after.stages[0].status).toBe("done"); // unchanged
  });

  it("failed carries the job error; cancelled preserves position", () => {
    let v = createJobView("job-1", "transcription", 0);
    v = reduceJobEvent(v, ev({ stage: "cleaning" }));
    const f = reduceJobEvent(
      v,
      ev({ phase: "failed", error: { code: "JOB_FAILED", message: "x" } }),
    );
    expect(f.phase).toBe("failed");
    expect(f.error?.code).toBe("JOB_FAILED");
    expect(f.stages[2].status).toBe("active"); // where it died
    const c = reduceJobEvent(v, ev({ phase: "cancelled" }));
    expect(c.phase).toBe("cancelled");
    expect(c.stages[2].status).toBe("active");
  });

  it("markCancelling only applies while running; markJobDead is terminal", () => {
    let v = createJobView("job-1", "transcription", 0);
    v = markCancelling(v);
    expect(v.phase).toBe("cancelling");
    const dead = markJobDead(v, { code: ERR.WORKER_CRASHED, message: "x" });
    expect(dead.phase).toBe("failed");
    expect(dead.error?.code).toBe(ERR.WORKER_CRASHED);
    // A settled job is never resurrected.
    const done = reduceJobEvent(dead, {
      jobId: "job-1",
      phase: "completed",
    });
    expect(done.phase).toBe("failed");
  });

  it("stage ids cover the copy deck order (7 stages)", () => {
    expect(TRANSCRIPTION_STAGE_IDS).toEqual([
      "preparing_audio",
      "transcribing",
      "cleaning",
      "analyzing_rhythm",
      "quantizing",
      "building_score",
      "rendering",
    ]);
    expect(initialStages()).toHaveLength(7);
  });
});

describe("review contract", () => {
  it("extracts the open-issue count from a completed result", () => {
    expect(
      extractReviewIssueCount({ reviewIssues: [{ id: "ri-1", reason: "x" }] }),
    ).toBe(1);
    expect(extractReviewIssueCount({ reviewIssueCount: 5 })).toBe(5);
    expect(extractReviewIssueCount({})).toBe(0);
    expect(extractReviewIssueCount(null)).toBe(0);
    expect(extractReviewIssueCount({ reviewIssues: "nope" })).toBe(0);
  });

  it("maps known reasons to deck keys, unknown to 'other'", () => {
    expect(reviewReasonCopyKey("quantization_ambiguous")).toBe(
      "quantization_ambiguous",
    );
    expect(reviewReasonCopyKey("low_model_confidence")).toBe(
      "low_model_confidence",
    );
    expect(reviewReasonCopyKey("future_reason_x")).toBe("other");
  });
});

